def count_random_pictures(n, m):
    if n == 1:
        return pow(2, m, MOD)
    if m == 1:
        return pow(2, n, MOD)

    # Initialize the DP arrays
    prev_row = [0] * (1 << m)
    current_row = [0] * (1 << m)

    # Base case: there are 2^m ways to color the first row
    for mask in range(1 << m):
        if is_valid(mask):
            prev_row[mask] = 1

    # Fill the DP table
    for i in range(1, n):
        for mask in range(1 << m):
            if is_valid(mask):
                for prev_mask in range(1 << m):
                    if is_compatible(prev_mask, mask):
                        current_row[mask] = (current_row[mask] + prev_row[prev_mask]) % MOD
        prev_row, current_row = current_row, [0] * (1 << m)

    # Sum up all valid configurations for the last row
    result = sum(prev_row) % MOD
    return result

def is_valid(mask):
    """Check if the mask represents a valid row (no two adjacent cells are the same)."""
    for j in range(m):
        if (mask >> j) & 1 == ((mask >> (j + 1)) & 1) and j + 1 < m:
            return False
    return True

def is_compatible(prev_mask, mask):
    """Check if two rows are compatible (no two adjacent cells in the same column are the same)."""
    for j in range(m):
        if (prev_mask >> j) & 1 == (mask >> j) & 1:
            return False
    return True

